import React from "react";
import { useEffect, useState } from "react";
import { GetLoggedinUserToken } from "../utilities/getLoggedinUserToken";
import appsettings from "../../appsettings.json"


const apiendpoints = appsettings.ApiEndpoints;


function ReportDefiner() {

    const [rptUrl, setRptUrl] = useState("");


    /* Fetch data from Api */
    const FetchToken = async () => {
        const token = await GetLoggedinUserToken();

        if (token.hdr) {
            if (token.hdr.rst === "SUCCESS") {

                // let reportUrl = apiendpoints.reportUrl+ "?t=" + token.body.token;

                // let reportUrl = "http://localhost/saasisrpt/?t=" + token.body.token;

                let reportUrl = "http://rd.saasis.co/?t=" + token.body.token;

                setRptUrl(reportUrl);
            }
        }
    };

    /*  Use Effect */
    useEffect(() => { FetchToken(); }, []);

    return (
        <>
            <iframe src={rptUrl} width="100%" height="1000"></iframe>
        </>
    );

}

export default ReportDefiner;