import api from "../api/Webcall";
import { generateUUID } from "./utils";
import appsettings from "../../appsettings.json"

const apiendpoints = appsettings.ApiEndpoints;

export const GetLoggedinUserToken = async () => {

   let Response;

   const reqHdr = {};
   const convID = generateUUID();
   const frmHdr = { convid: convID, tag: "get loggedin user token", orgid: "", vendid: "0" };
   const frmData = {}
   const data = { hdr: frmHdr, body: frmData };

   await api.post(apiendpoints.userToken, data, reqHdr).then(function (response) {
      Response = response.data;
   });

   return Response;

};
